1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"os"
7		"strings"
8	
9		"github.com/entireio/entire-brain/internal/apiurl"
10	
11		"github.com/spf13/cobra"
12		"golang.org/x/mod/semver"
13	)
14	
15	// minHostCLIVersion is the first host CLI release that ships `entire repo view
16	// --json` (entireio/cli#2758), which placement resolution depends on. Only
17	// connect's placement shell-out checks it: local-only brain use and explicit
18	// --repo-id/--api-url never touch the host CLI version. Empty disables the
19	// gate explicitly. A var so tests can exercise the gate.
20	var minHostCLIVersion = "0.11.6"
21	
22	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
23	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
24	// and its cell API base URL, both top-level fields.
25	type hostedPlacement struct {
26		RepoID string `json:"repoId"`
27		APIURL string `json:"apiUrl"`
28	}
29	
30	type connectOptions struct {
31		repoID string
32		apiURL string
33	}
34	
35	func newConnectCommand(opts Options) *cobra.Command {
36		var connectOpts connectOptions
37		cmd := &cobra.Command{
38			Use:   "connect",
39			Short: "Bind this repository to its hosted brain explicitly",
40			Long: `connect binds this repository to its hosted brain: it records the repo id and
41	API base URL (non-secrets only — the host CLI's own login mints a fresh token
42	per sync), then runs one immediate sync so the first pull happens right away.
43	
44	Running connect (or the onboarding flow) is the ONLY way a repository starts
45	syncing: by default memories stay local and background triggers never connect
46	a repo on their own. Placement resolves through the host CLI (entire repo
47	view); pass --repo-id and --api-url to bypass resolution — a non-default cell
48	or a staging target. Re-running connect re-joins after 'entire brain
49	disconnect'.`,
50			Args: cobra.NoArgs,
51			RunE: func(cmd *cobra.Command, args []string) error {
52				return runConnect(cmd, opts, connectOpts)
53			},
54		}
55		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
56		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
57		return cmd
58	}
59	
60	func runConnect(cmd *cobra.Command, opts Options, connectOpts connectOptions) error {
61		ctx := cmd.Context()
62		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
63		if err != nil {
64			return err
65		}
66		if !local {
67			return fmt.Errorf("connect requires a local repository path")
68		}
69		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
70		if err != nil {
71			return err
72		}
73	
74		repoID := strings.TrimSpace(connectOpts.repoID)
75		apiURL := strings.TrimSpace(connectOpts.apiURL)
76		if repoID == "" || apiURL == "" {
77			resolved, placementErr := resolveHostedPlacement(ctx, opts.Runner, repoDir)
78			if placementErr != nil {
79				// An already-connected (or disconnected — the opt-out keeps its
80				// coordinates) repo stays re-connectable without flags: re-connect
81				// means re-sync, not re-resolve.
82				if existing, present, readErr := readHostedRepoBinding(storage.BrainDir); readErr == nil && present && existing.RepoID != "" {
83					resolved = hostedPlacement{RepoID: existing.RepoID, APIURL: existing.BaseURL}
84				} else {
85					return fmt.Errorf("connect: resolve hosted placement (`entire repo view --json`): %w; pass --repo-id and --api-url explicitly", placementErr)
86				}
87			}
88			if repoID == "" {
89				repoID = resolved.RepoID
90			}
91			if apiURL == "" {
92				apiURL = resolved.APIURL
93			}
94		}
95		// Whether this run re-affirms an existing connection decides the success
96		// headline: "connected" must not read like a state change when nothing
97		// changed.
98		existing, existingPresent, existingErr := readHostedRepoBinding(storage.BrainDir)
99		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
100		if err != nil {
101			return fmt.Errorf("connect: %w", err)
102		}
103		already := existingErr == nil && existingPresent && !existing.OptedOut &&
104			existing.RepoID == binding.RepoID && existing.BaseURL == binding.BaseURL
105		// A connected repo wants the push-beat upload: install our pre-push hook
106		// (chained beside whatever hook owns the slot). Best-effort — a hook
107		// problem must not fail the connect.
108		if hookState, hookPath, hookErr := installPushHook(ctx, opts, repoDir); hookErr != nil {
109			fmt.Fprintf(cmd.ErrOrStderr(), "connect: push hook not installed (uploads ride the daemon tick): %v\n", hookErr)
110		} else if hookState == pushHookSharedDir {
111			fmt.Fprintf(cmd.ErrOrStderr(), "connect: core.hooksPath (%s) is shared across repos; push hook not managed — uploads ride the daemon tick\n", hookPath)
112		}
113		// The kill switch suppresses every sync this command is about to promise,
114		// so say that instead of "now syncing". The binding still gets recorded:
115		// the environment only subtracts, and unsetting it resumes syncing.
116		if brainNoEgressMode() {
117			renderHostedBanner(cmd.OutOrStdout(),
118				"Connected: repo "+binding.RepoID+" — but nothing syncs while "+noEgressToggleName()+" is set",
119				"The binding is recorded and memories stay local. Unset "+noEgressToggleName()+" to start syncing.")
120			return nil
121		}
122		// Connect doubles as the initial pull so a fresh clone receives team
123		// memories immediately. The sync runs BEFORE the banner so the headline
124		// reports what actually happened: a connect whose first pull failed has
125		// not started syncing, and claiming so hides a dead connection.
126		outcome, err := hostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage, hostedSyncBranch(ctx, opts.Runner, repoDir))
127		if err != nil {
128			return err
129		}
130		if !outcome.PullSucceeded {
131			verdict := "failed"
132			if !outcome.Attempted {
133				verdict = "did not run"
134			}
135			return fmt.Errorf("connect: repo %s is bound, but the first sync %s (details above); memories stay local until a sync succeeds — fix the cause and re-run '%s'",
136				binding.RepoID, verdict, brainInvocation(os.LookupEnv, "connect"))
137		}
138		headline := "Connected: repo " + binding.RepoID + " is now syncing memories"
139		if already {
140			headline = "Already connected: repo " + binding.RepoID + " — memories are syncing"
141		}
142		renderHostedBanner(cmd.OutOrStdout(), headline,
143			"Memories sync periodically, at session end, and on git push. Teammates' memories merge into this repo's local brain.")
144		return nil
145	}
146	
147	// normalizeHostedBinding validates the target and strips a quoted /api/v1
148	// suffix. Cell URLs are commonly quoted with that prefix (repo view's apiUrl,
149	// docs examples), but the factsync client appends /api/v1/repos/... itself —
150	// storing the suffix would 404 every sync. OptedOut is false: a fresh binding
151	// is an opt-in.
152	func normalizeHostedBinding(repoID, apiURL string) (hostedRepoBinding, error) {
153		if strings.TrimSpace(repoID) == "" {
154			return hostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
155		}
156		validated, err := apiurl.Validate(apiURL)
157		if err != nil {
158			return hostedRepoBinding{}, err
159		}
160		return hostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}, nil
161	}
162	
163	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
164	// there, including an opt-out — running connect is how the user opts back in.
165	func bindHostedRepo(brainDir, repoID, apiURL string) (hostedRepoBinding, error) {
166		binding, err := normalizeHostedBinding(repoID, apiURL)
167		if err != nil {
168			return hostedRepoBinding{}, err
169		}
170		if err := writeHostedRepoBinding(brainDir, binding); err != nil {
171			return hostedRepoBinding{}, err
172		}
173		return binding, nil
174	}
175	
176	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
177	// placement.
178	func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error) {
179		ctx, cancel := context.WithTimeout(ctx, hostedShellOutTimeout)
180		defer cancel()
181		if err := checkHostCLIVersion(ctx, runner, repoDir, minHostCLIVersion); err != nil {
182			return hostedPlacement{}, err
183		}
184		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "repo", "view", "--json")
185		if err != nil {
186			return hostedPlacement{}, err
187		}
188		var result hostedPlacement
189		if err := decodeHostCLIJSON(stdout, &result); err != nil {
190			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
191		}
192		return result, nil
193	}
194	
195	// checkHostCLIVersion refuses placement resolution on a host CLI older than
196	// min, so the failure says "upgrade" instead of repo view's unknown-command
197	// noise. A missing CLI or an unrecognized version line (dev builds) passes:
198	// the repo view call itself is the authority on whether the command exists.
199	func checkHostCLIVersion(ctx context.Context, runner CommandRunner, repoDir, min string) error {
200		if min == "" {
201			return nil
202		}
203		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "version")
204		if err != nil {
205			return nil
206		}
207		// First line is "Entire CLI <version>", on some builds with a trailing
208		// "(<commit>)". Take the first field that parses as semver, not a fixed
209		// position, so a build suffix cannot fail-open the gate.
210		line, _, _ := strings.Cut(strings.TrimSpace(string(stdout)), "\n")
211		got := ""
212		for _, field := range strings.Fields(line) {
213			if v := "v" + strings.TrimPrefix(field, "v"); semver.IsValid(v) {
214				got = v
215				break
216			}
217		}
218		if got == "" {
219			return nil
220		}
221		// Compare the release core only: a prerelease or pseudo-version of min
222		// (nightly, git describe) ranks below min in full semver order yet may
223		// already ship repo view — those builds pass and repo view stays the
224		// authority.
225		core := strings.TrimSuffix(got, semver.Build(got))
226		core = strings.TrimSuffix(core, semver.Prerelease(core))
227		if semver.Compare(core, "v"+min) >= 0 {
228			return nil
229		}
230		return fmt.Errorf("entire CLI %s does not support `entire repo view` (needs %s or newer); upgrade the entire CLI and re-run connect", strings.TrimPrefix(got, "v"), min)
231	}
