1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"fmt"
7		"io"
8		"os"
9		"os/exec"
10		"sort"
11		"strings"
12		"sync"
13		"time"
14	)
15	
16	// CommandRunner runs external commands. Tests replace it so export behavior
17	// can be verified without requiring a real Entire checkout.
18	type CommandRunner interface {
19		Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error)
20	}
21	
22	// EnvironmentCommandRunner is the narrow capability used when a child process
23	// needs an operation-specific environment safety boundary. Keeping it optional
24	// avoids making every test runner and provider adapter environment-aware while
25	// still letting security-sensitive callers fail closed when the capability is
26	// unavailable.
27	type EnvironmentCommandRunner interface {
28		RunWithEnv(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error)
29	}
30	
31	// CommandStreamer is an optional capability for CommandRunner implementations
32	// that can expose a child process's stdout incrementally instead of buffering
33	// the entire output. The semantic provider snapshot can grow to hundreds of
34	// megabytes on large repositories, so the indexer streams it record-by-record
35	// rather than holding it all in memory. Runners that do not implement this
36	// interface fall back to the buffered Run path.
37	type CommandStreamer interface {
38		Stream(ctx context.Context, dir, name string, args ...string) (CommandStream, error)
39	}
40	
41	// GitCatFileBatcher is an optional capability: a runner whose git spawn policy
42	// matches ExecRunner's may have repeated local object reads served by a shared
43	// long-lived `git cat-file --batch` child (see git_catfile_batch.go). It is a
44	// deliberate opt-in, not an inherited seam: batching bypasses Run entirely, so
45	// a wrapper runner that intercepts per-call behavior must not claim it by
46	// accident.
47	type GitCatFileBatcher interface {
48		CatFileBatchAllowed() bool
49	}
50	
51	func (ExecRunner) CatFileBatchAllowed() bool { return true }
52	
53	// hardenedGitInvocation is the one assembly point for how this binary spawns
54	// git: hardened args plus the repository filter-driver overrides merged into
55	// the environment. The buffered runner, the streaming runner, and the cat-file
56	// batch child all consume it, so a new hardening bit cannot cover one spawn
57	// path and miss another (see git_harden.go).
58	func hardenedGitInvocation(ctx context.Context, dir string, env map[string]string, args ...string) (hardenedArgs, mergedEnv []string, err error) {
59		hardenedArgs = hardenedGitArgs(args...)
60		overrides, err := repoFilterDriverOverrides(ctx, dir)
61		if err != nil {
62			return nil, nil, err
63		}
64		return hardenedArgs, gitConfigOverrideEnv(mergeCommandEnv(os.Environ(), env), overrides), nil
65	}
66	
67	// CommandStream is a started command whose stdout is consumed incrementally.
68	// Callers must read Stdout to completion (or drain it) before calling Wait.
69	type CommandStream interface {
70		// Stdout returns the live stdout reader.
71		Stdout() io.Reader
72		// Wait blocks until the command exits, returning the captured stderr and
73		// the raw exit error (unwrapped, so callers can format it).
74		Wait() (stderr []byte, err error)
75		// Close releases any resources. It is safe to call after Wait.
76		Close() error
77	}
78	
79	// streamStderrCap bounds how much stderr a streamed command may retain in
80	// memory. Provider stderr is only used for diagnostics, so a generous cap keeps
81	// error messages useful without letting a misbehaving provider exhaust memory.
82	const streamStderrCap = 256 * 1024
83	
84	// commandWaitDelay bounds how long a command may keep the runner blocked after
85	// its context is cancelled.
86	//
87	// exec.CommandContext kills the child on cancellation, but cmd.Run and cmd.Wait
88	// return only once every writer of the stdout/stderr pipes has closed. A child
89	// that spawns a grandchild inheriting those descriptors therefore keeps the
90	// runner blocked for as long as the GRANDCHILD lives, long after the deadline
91	// passed and the child was killed. Every context deadline in this binary is
92	// implemented on top of this runner, so without a WaitDelay a single stray
93	// grandchild makes all of them unenforceable: measured at 30s of wait against a
94	// 300ms deadline.
95	//
96	// WaitDelay bounds waiting for process exit and inherited pipes after
97	// cancellation. CommandContext kills the direct child, not its process group. It is a
98	// backstop, not a timeout: a command that exits normally is never affected, and
99	// the delay only starts counting once the context is already cancelled.
100	const commandWaitDelay = 2 * time.Second
101	
102	type ExecRunner struct{}
103	
104	func (ExecRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
105		return runExecCommand(ctx, dir, nil, name, args...)
106	}
107	
108	func (ExecRunner) RunWithEnv(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
109		return runExecCommand(ctx, dir, env, name, args...)
110	}
111	
112	func runExecCommand(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
113		var mergedEnv []string
114		if name == "git" {
115			// The filter neutralizers travel in the environment, not in argv; see
116			// git_harden_filters.go for why `-c` cannot express them safely.
117			var err error
118			args, mergedEnv, err = hardenedGitInvocation(ctx, dir, env, args...)
119			if err != nil {
120				return nil, nil, err
121			}
122		} else if len(env) > 0 {
123			mergedEnv = mergeCommandEnv(os.Environ(), env)
124		}
125		cmd := exec.CommandContext(ctx, name, args...)
126		cmd.WaitDelay = commandWaitDelay
127		if dir != "" {
128			cmd.Dir = dir
129		}
130		if mergedEnv != nil {
131			cmd.Env = mergedEnv
132		}
133	
134		var stdout bytes.Buffer
135		var stderr bytes.Buffer
136		cmd.Stdout = &stdout
137		cmd.Stderr = &stderr
138	
139		err := cmd.Run()
140		if err != nil {
141			if stderr.Len() > 0 {
142				return stdout.Bytes(), stderr.Bytes(), fmt.Errorf("%s %v: %w: %s", name, args, err, stderr.String())
143			}
144			return stdout.Bytes(), stderr.Bytes(), fmt.Errorf("%s %v: %w", name, args, err)
145		}
146		return stdout.Bytes(), stderr.Bytes(), nil
147	}
148	
149	func mergeCommandEnv(base []string, overrides map[string]string) []string {
150		out := make([]string, 0, len(base)+len(overrides))
151		for _, entry := range base {
152			key, _, ok := strings.Cut(entry, "=")
153			if ok {
154				if _, replaced := overrides[key]; replaced {
155					continue
156				}
157			}
158			out = append(out, entry)
159		}
160		keys := make([]string, 0, len(overrides))
161		for key := range overrides {
162			keys = append(keys, key)
163		}
164		sort.Strings(keys)
165		for _, key := range keys {
166			value := overrides[key]
167			out = append(out, key+"="+value)
168		}
169		return out
170	}
171	
172	// Stream starts name and exposes its stdout as a streaming reader. stderr is
173	// captured into a bounded buffer by exec's own copy goroutine, so reading
174	// stdout never blocks on stderr.
175	func (ExecRunner) Stream(ctx context.Context, dir, name string, args ...string) (CommandStream, error) {
176		var mergedEnv []string
177		if name == "git" {
178			var err error
179			args, mergedEnv, err = hardenedGitInvocation(ctx, dir, nil, args...)
180			if err != nil {
181				return nil, err
182			}
183		}
184		cmd := exec.CommandContext(ctx, name, args...)
185		cmd.WaitDelay = commandWaitDelay
186		if dir != "" {
187			cmd.Dir = dir
188		}
189		if mergedEnv != nil {
190			cmd.Env = mergedEnv
191		}
192		stdout, err := cmd.StdoutPipe()
193		if err != nil {
194			return nil, err
195		}
196		stderr := &cappedBuffer{limit: streamStderrCap}
197		cmd.Stderr = stderr
198		if err := cmd.Start(); err != nil {
199			return nil, err
200		}
201		return &execStream{cmd: cmd, stdout: stdout, stderr: stderr}, nil
202	}
203	
204	type execStream struct {
205		cmd    *exec.Cmd
206		stdout io.ReadCloser
207		stderr *cappedBuffer
208	}
209	
210	func (s *execStream) Stdout() io.Reader { return s.stdout }
211	
212	func (s *execStream) Wait() ([]byte, error) {
213		err := s.cmd.Wait()
214		return s.stderr.Bytes(), err
215	}
216	
217	func (s *execStream) Close() error {
218		// cmd.Wait closes the stdout pipe; closing again is harmless and covers the
219		// case where the caller never reached Wait.
220		return s.stdout.Close()
221	}
222	
223	// cappedBuffer is an io.Writer that retains at most limit bytes. Writes past the
224	// cap are counted but discarded, so diagnostics keep the head of the output.
225	//
226	// The mutex exists because exec's copy goroutine writes while a reader can
227	// call Bytes after Wait returned early: with WaitDelay set, Wait may return
228	// on a forced pipe close while the copier is still draining its final read.
229	type cappedBuffer struct {
230		mu    sync.Mutex
231		buf   bytes.Buffer
232		limit int
233	}
234	
235	func (c *cappedBuffer) Write(p []byte) (int, error) {
236		c.mu.Lock()
237		defer c.mu.Unlock()
238		if room := c.limit - c.buf.Len(); room > 0 {
239			if room < len(p) {
240				c.buf.Write(p[:room])
241			} else {
242				c.buf.Write(p)
243			}
244		}
245		return len(p), nil
246	}
247	
248	func (c *cappedBuffer) Bytes() []byte {
249		c.mu.Lock()
250		defer c.mu.Unlock()
251		// Copy: the caller must not observe later writes through a shared backing
252		// array.
253		return bytes.Clone(c.buf.Bytes())
254	}
