	want := "connect: " + hostMessage + "\nOr pass --repo-id and --api-url explicitly"
	if err.Error() != want {
		t.Fatalf("error must be the host message plus the flags hint, got:\n%s\nwant:\n%s", err.Error(), want)
	}
}

